mod storage;

use std::io::stdout;

use clap::{Parser, Subcommand};
use tracing::{debug, error, info, warn};
use tracing_appender::{non_blocking, rolling};
use tracing_subscriber::{EnvFilter, fmt, layer::SubscriberExt, util::SubscriberInitExt};

use config::DataPaths;
use error::SuperfuseError;
use storage::{FileMapping, SqlitePool};

use crate::config::{SuperpositionConfig, fs_config, init_superposition_provider};

#[derive(Parser, Debug)]
#[command(name = "superfuse", about = "Virtual filesystem for templated configs")]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand, Debug)]
enum Commands {
    /// Start the superfuse filesystem
    Start {
        mount_point: String,
        /// Automatically unmount on process exit
        #[arg(short = 'u', long, default_value_t = true)]
        auto_unmount: bool,
        /// Allow root user to access filesystem
        #[arg(short, long, default_value_t = true)]
        allow_root: bool,
        /// Number of threads to use
        #[arg(short, long, default_value_t = 4)]
        n_threads: usize,
        /// Use `FUSE_DEV_IOC_CLONE` to give each worker thread its own fd.
        /// This enables more efficient request processing
        /// when multiple threads are used. Requires Linux 4.5+.
        #[arg(short, long, default_value_t = true)]
        clone_fd: bool,
    },
    /// Add a new file mapping
    Add {
        /// Virtual path in the FUSE filesystem (e.g., /config/app.yaml)
        #[arg(short, long)]
        path: String,
        /// Path to the template file (handlebars format)
        #[arg(short, long)]
        template: String,
    },
    /// Remove an existing file mapping
    Remove {
        /// Virtual path to remove
        #[arg(short, long)]
        path: String,
    },
    /// Update an existing file mapping
    Update {
        /// Virtual path to update
        #[arg(short, long)]
        path: String,
        /// New template file path
        #[arg(short, long)]
        template: String,
    },
    /// List all file mappings
    List,
}

fn init_tracing(log_dir: &std::path::Path) -> Result<(), SuperfuseError> {
    let file_appender = rolling::daily(log_dir, "superfuse.log");
    let (non_blocking, _guard) = non_blocking(file_appender);

    let log_level = std::env::var("SUPERFUSE_LOG_LEVEL").unwrap_or_else(|_| "info".to_string());

    let env_filter =
        EnvFilter::try_from_default_env().unwrap_or_else(|_| EnvFilter::new(&log_level));

    tracing_subscriber::registry()
        .with(env_filter)
        .with(fmt::layer().with_writer(stdout))
        .with(fmt::layer().with_writer(non_blocking).with_ansi(false))
        .init();

    debug!(log_level = %log_level, "tracing initialized");
    Ok(())
}

fn validate_template_exists(template_path: &str) -> Result<std::path::PathBuf, SuperfuseError> {
    let path = std::path::PathBuf::from(template_path);
    if !path.exists() {
        return Err(SuperfuseError::TemplateNotFound(path));
    }
    Ok(path)
}

fn print_mappings(mappings: &[FileMapping]) {
    if mappings.is_empty() {
        println!("No mappings found.");
        return;
    }

    println!(
        "{:<6} {:<40} {:<40} {:<20}",
        "ID", "Virtual Path", "Template Path", "Updated"
    );
    println!("{}", "-".repeat(106));
    for m in mappings {
        println!(
            "{:<6} {:<40} {:<40} {:<20}",
            m.id,
            truncate(&m.virtual_path, 40),
            truncate(&m.template_path, 40),
            truncate(&m.last_modified_at, 20)
        );
    }
}

fn truncate(s: &str, max_len: usize) -> String {
    if s.len() > max_len {
        format!("{}...", &s[..max_len.saturating_sub(3)])
    } else {
        s.to_string()
    }
}

#[tokio::main]
async fn main() {
    // Load .env file (non-fatal if missing)
    if dotenvy::dotenv().is_err() {
        // Only warn if user is trying to use provider features
        warn!("no .env file found, using environment variables");
    }

    // Initialize data directory
    let Ok(data_paths) = DataPaths::init().map_err(|e| eprintln!("Data path Error: {e}")) else {
        std::process::exit(1);
    };

    // Initialize tracing (logs to data directory + stdout)
    if let Err(e) = init_tracing(&data_paths.logs) {
        eprintln!("Failed to initialize logging: {e}");
        std::process::exit(1);
    }

    // Initialize database pool (using r2d2_sqlite for thread safety)
    let Ok(pool) = storage::init_db(&data_paths.db)
        .map_err(|e| error!(error = %e, "failed to initialize database"))
    else {
        std::process::exit(1);
    };

    // Parse CLI
    let cli = Cli::parse();

    // Dispatch commands
    if let Err(e) = handle_command(cli, pool, &data_paths).await {
        error!(error = %e, "command failed");
        std::process::exit(1);
    }
}

async fn handle_command(
    cli: Cli,
    pool: SqlitePool,
    paths: &DataPaths,
) -> Result<(), SuperfuseError> {
    match cli.command {
        Commands::Start {
            mount_point,
            auto_unmount,
            allow_root,
            n_threads,
            clone_fd,
        } => {
            // Initialize superposition provider
            let config = SuperpositionConfig::init()?;
            let provider = init_superposition_provider(&config).await?;

            // Create the FUSE filesystem with the connection pool
            let fs = storage::SuperfuseFileSystem::new(pool, paths.clone(), provider);

            // Mount the filesystem using spawn_mount2 so we can handle signals
            info!(mount_point = %mount_point, "mounting filesystem");
            let fs_config = fs_config(&mount_point, auto_unmount, allow_root, n_threads, clone_fd);
            let session = fuser::spawn_mount2(fs, &mount_point, &fs_config).map_err(|e| {
                error!(error = %e, "failed to mount filesystem");
                SuperfuseError::Io(e)
            })?;

            info!("filesystem mounted, waiting for shutdown signal");

            // Wait for SIGINT (Ctrl+C), SIGTERM, or SIGHUP
            let mut sigint =
                tokio::signal::unix::signal(tokio::signal::unix::SignalKind::interrupt())
                    .map_err(|e| SuperfuseError::Io(e))?;
            let mut sigterm =
                tokio::signal::unix::signal(tokio::signal::unix::SignalKind::terminate())
                    .map_err(|e| SuperfuseError::Io(e))?;
            let mut sighup = tokio::signal::unix::signal(tokio::signal::unix::SignalKind::hangup())
                .map_err(|e| SuperfuseError::Io(e))?;

            tokio::select! {
                _ = sigint.recv() => info!("received SIGINT"),
                _ = sigterm.recv() => info!("received SIGTERM"),
                _ = sighup.recv() => info!("received SIGHUP"),
            }

            // Cleanly unmount and join the background thread
            info!(mount_point = %mount_point, "unmounting filesystem");
            session.umount_and_join().map_err(|e| {
                error!(error = %e, "failed to unmount filesystem");
                SuperfuseError::Io(e)
            })?;
            info!("filesystem unmounted successfully");
        }
        Commands::Add { path, template } => {
            validate_template_exists(&template)?;
            let canonical = std::fs::canonicalize(&template).map_err(SuperfuseError::Io)?;
            let template_path = canonical.display().to_string();

            // Get a connection from the pool for this CLI operation
            let conn = pool.get().map_err(|e| {
                error!(error = %e, "failed to get connection from pool");
                SuperfuseError::Database(rusqlite::Error::InvalidQuery)
            })?;

            let mapping = storage::add_mapping(&conn, &path, &template_path)?;
            info!(id = mapping.id, path = %mapping.virtual_path, "mapping added");
            println!(
                "Added mapping: {} -> {}",
                mapping.virtual_path, mapping.template_path
            );
        }
        Commands::Remove { ref path } => {
            let conn = pool.get().map_err(|e| {
                error!(error = %e, "failed to get connection from pool");
                SuperfuseError::Database(rusqlite::Error::InvalidQuery)
            })?;

            storage::remove_mapping(&conn, path)?;
            println!("Removed mapping: {}", path);
        }
        Commands::Update { ref path, template } => {
            validate_template_exists(&template)?;
            let canonical = std::fs::canonicalize(&template).map_err(SuperfuseError::Io)?;
            let template_path = canonical.display().to_string();

            let conn = pool.get().map_err(|e| {
                error!(error = %e, "failed to get connection from pool");
                SuperfuseError::Database(rusqlite::Error::InvalidQuery)
            })?;

            let mapping = storage::update_mapping(&conn, path, &template_path)?;
            println!(
                "Updated mapping: {} -> {}",
                mapping.virtual_path, mapping.template_path
            );
        }
        Commands::List => {
            let conn = pool.get().map_err(|e| {
                error!(error = %e, "failed to get connection from pool");
                SuperfuseError::Database(rusqlite::Error::InvalidQuery)
            })?;

            let mappings = storage::list_mappings(&conn)?;
            print_mappings(&mappings);
        }
    }
    Ok(())
}

use std::{
    collections::HashMap,
    fmt::Display,
    path::{Path, PathBuf},
    str::FromStr,
};

use directories::ProjectDirs;
use fuser::SessionACL;
use superposition_provider::{SuperpositionProvider, SuperpositionProviderOptions};
use tracing::{debug, info, warn};

use crate::error::SuperfuseError;

/// Superposition connection configuration loaded from environment variables.
#[derive(Debug, Clone)]
pub struct SuperpositionConfig {
    pub endpoint: String,
    pub token: String,
    pub org_id: String,
    pub workspace_id: String,
    pub additional_headers: HashMap<String, String>,
}

impl SuperpositionConfig {
    pub fn init() -> Result<Self, SuperfuseError> {
        let cfg = SuperpositionConfig {
            endpoint: require_env(
                "SUPERPOSITION_ENDPOINT",
                "http://localhost:8080".to_string(),
            ),
            token: require_env("SUPERPOSITION_TOKEN", "123456".to_string()),
            org_id: require_env("SUPERPOSITION_ORG_ID", "localorg".into()),
            workspace_id: require_env("SUPERPOSITION_WORKSPACE_ID", "localworkspace".into()),
            additional_headers: HashMap::new(),
        };
        debug!(
            endpoint = %cfg.endpoint,
            org_id = %cfg.org_id,
            workspace_id = %cfg.workspace_id,
            additional_headers = ?cfg.additional_headers,
            "loaded superposition config"
        );
        Ok(cfg)
    }
}

/// Resolved paths for the superfuse data directory.
#[derive(Debug, Clone)]
pub struct DataPaths {
    // pub root: PathBuf,
    pub db: PathBuf,
    pub logs: PathBuf,
}

impl DataPaths {
    /// Resolve and create the data directory tree.
    pub fn init() -> Result<Self, SuperfuseError> {
        let proj =
            ProjectDirs::from("com", "juspay", "superfuse").ok_or(SuperfuseError::NoDataDir)?;

        let root = proj.data_dir().to_path_buf();
        let db = root.join("superfuse.db");
        let logs = root.join("logs");

        for dir in [&root, &logs] {
            ensure_dir(dir)?;
        }

        info!(path = %root.display(), "data directory ready");
        debug!(db = %db.display(), logs = %logs.display(), "resolved data paths");

        Ok(Self { db, logs })
    }
}

fn ensure_dir(path: &Path) -> Result<(), SuperfuseError> {
    if !path.exists() {
        std::fs::create_dir_all(path).map_err(|source| SuperfuseError::CreateDir {
            path: path.to_path_buf(),
            source,
        })?;
        debug!(path = %path.display(), "created directory");
    }
    Ok(())
}

pub fn require_env<T>(key: &'static str, default: T) -> T
where
    T: FromStr + Display + std::fmt::Debug,
    <T as FromStr>::Err: std::fmt::Debug + std::error::Error,
{
    std::env::var(key)
        .map_err(|_| {
            warn!("No environment variable found for {key}, using default value: {default}")
        })
        .ok()
        .and_then(|val| val.parse::<T>().ok())
        .unwrap_or(default)
}

pub async fn init_superposition_provider(
    config: &SuperpositionConfig,
) -> Result<SuperpositionProvider, SuperfuseError> {
    let options = SuperpositionProviderOptions {
        endpoint: config.endpoint.clone(),
        token: config.token.clone(),
        org_id: config.org_id.clone(),
        workspace_id: config.workspace_id.clone(),
        fallback_config: None,
        evaluation_cache: Some(superposition_provider::EvaluationCacheOptions {
            size: Some(require_env("SUPERPOSITION_CACHE_SIZE", 500)),
            ttl: Some(require_env("SUPERPOSITION_CACHE_TTL", 3600)),
        }),
        // evaluation_cache: None,
        refresh_strategy: superposition_provider::RefreshStrategy::Polling(
            superposition_provider::PollingStrategy {
                interval: require_env("SUPERPOSITION_POLL_FREQUENCY", 60),
                timeout: Some(require_env("SUPERPOSITION_POLL_TIMEOUT", 30)),
            },
        ),
        experimentation_options: None,
    };
    let provider = SuperpositionProvider::new(options);
    provider
        .init()
        .await
        .map_err(|e| SuperfuseError::Provider(e.to_string()))?;
    Ok(provider)
}

pub fn fs_config(
    mount_point: &str,
    auto_unmount: bool,
    allow_root: bool,
    n_threads: usize,
    clone_fd: bool,
) -> fuser::Config {
    let mut config = fuser::Config::default();
    if auto_unmount {
        config.mount_options.push(fuser::MountOption::AutoUnmount);
    }
    if allow_root {
        config.acl = SessionACL::RootAndOwner;
    }
    if config
        .mount_options
        .contains(&fuser::MountOption::AutoUnmount)
        && config.acl != SessionACL::RootAndOwner
    {
        config.acl = SessionACL::All;
    }
    config.n_threads = Some(n_threads);
    config.clone_fd = clone_fd;
    config.mount_options.extend([
        fuser::MountOption::RO,
        fuser::MountOption::FSName(mount_point.to_string()),
    ]);
    config
}
